autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rwnpc0601={id="rwnpc0601",baseId="rwnpc0601",combatid={1,1001},name="老乞丐",teamMark=-1,canSee=1,caozuoName1="询问",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"35012",2}},{type="doc",args={"YEL老乞丐：小友可是常来平安小镇么？那小友可认识宝三娘？哈哈哈，那宝三娘做的粽子可是一绝啊。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL老乞丐：如今也正值端午，小友可否帮我去找宝三娘买个咸蛋粽子？她就住在平安南街的小院子，此时应当就在家里。NOR"}},{type="itemin",args={"23dwjqwp01",1}},{type="tips",args={"获得钱袋*1"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="showbutton",args={3,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL老乞丐：我不过一介漂泊客，名字不甚重要，小友想叫什么就叫什么。NOR","YEL老乞丐：小友放心，我定不会白白使唤。我行道多年，也收集了一些小玩意，想必小友会感兴趣。NOR","YEL老乞丐：那宝三娘就住在平安南街的小院子里，小友快去快回吧。NOR"}}},caozuoName3="给予",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="itresults",args={"23dwjqwp02",1,"大于等于",{{"doc",{"CYN老乞丐接过粽子后没有多语，细细地拆开棕叶，却只咬了一口便再无动作，似乎是陷入了思绪中。NOR"}},{"itemout",{"23dwjqwp02",1}},{"tips",{"失去咸蛋粽子*1"}},{"gaintab",{"35012",12}},{"showbutton",{2,0}},{"showbutton",{3,0}},{"showbutton",{4,1}}},{{"doc",{"YEL老乞丐：咸蛋粽子在哪呢？糊弄我可不厚道。NOR"}}}}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="gaintab",args={"35012",13}},{type="doc",args={"YEL老乞丐：说起来……第一次吃咸蛋馅的粽子还是我刚跟着师父的时候。他一个莽人哪会照顾小孩，折腾得我高烧不退，为了安慰我就想方设法的用咸鸭蛋包了一个粽子。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL老乞丐笑着摇了摇头：那粽子是真的很难吃……曾经嫌弃的不行，到如今竟还有些想了。不知小友有没有过如此想法。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL老乞丐：想起些无聊的旧事，难为小友听我啰嗦。这有些小礼还请小友收下，明日估计还需再劳烦小友，回见了。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="outgame",args={"hdrole0601"}},{type="outobject",args={"rwnpc0601"}},{type="refresh",args={}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rwnpc0602={id="rwnpc0602",baseId="rwnpc0602",combatid={1,1001},name="宝三娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"35012",4}},{type="doc",args={"YEL宝三娘：少侠跑错地了吧？买粽子该去菜来饭馆，怎得跑我这来了？NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL宝三娘：不过，有钱哪有不赚的道理。先将银子给我，我这就去准备材料。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"CYN宝三娘接过钱袋，正准备往外走，忽地停下脚步望向你，似乎有什么话要对你说。NOR"}},{type="itemout",args={"23dwjqwp01",1}},{type="tips",args={"失去钱袋*1"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="询问",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"35012",5}},{type="doc",args={"YEL宝三娘：虽说不该，但还是请少侠帮个忙。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL宝三娘：也不是什么大事，还请少侠帮我去趟石屋，找那里的路大江要几个咸鸭蛋。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL宝三娘：哎呦，我这也是为了少侠好嘛，我们双管齐下，事半功倍，也可以省点时间。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL宝三娘：就有劳少侠跑一趟石屋吧。NOR"}},{type="outobject",args={"rwnpc0602"}},{type="refresh",args={}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rwnpc0602a={id="rwnpc0602a",baseId="rwnpc0602",combatid={1,1001},name="宝三娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL宝三娘：少侠还等什么呢，把咸鸭蛋给我，我去做粽子了。NOR"}}},caozuoName2="给予",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="itemout",args={"23dwjqwp04",1}},{type="tips",args={"失去咸鸭蛋*1"}},{type="gaintab",args={"35012",11}},{type="doc",args={"CYN宝三娘接过咸鸭蛋后转身进了厨房。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"CYN你在原地等了好一会，宝三娘才端着一盆粽子出来，特别将一个粽子交予你。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL宝三娘：这就是少侠要的咸蛋粽子，少侠拿去给老友吧。NOR"}},{type="itemin",args={"23dwjqwp02",1}},{type="tips",args={"获得咸蛋粽子*1"}},{type="addobject",args={"rwwp01"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="redoc",args={"YEL宝三娘：少侠还有什么事么？NOR","YEL宝三娘：少侠若是饿了，刚出锅的粽子味美，少侠尽管品尝便是？NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rwnpc0603={id="rwnpc0603",baseId="rwnpc0603",combatid={1,1001},name="路大江",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"35012",7}},{type="doc",args={"YEL路大江：宝三娘叫你来的？她上次的钱还没给我呢！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL路大江：诶，我看你身手不错的样子，你帮我个忙，我直接将咸鸭蛋送你。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL路大江：你看到那只鸭子了么，它太能飞了，你帮我把它抓住，我就直接将咸鸭蛋送你，不收钱！NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL路大江：端午佳节，那不得杀鸡宰鸭吃顿好的？我想着捉几只鸭子去街上卖，本来好好的，这些鸭子突然就跟疯了一样都跑了出来，闹得鸭飞狗跳的。NOR","YEL路大江：就数那只灰毛鸭最能飞，为了捉它，我的脚都扭了。你帮捉住它，咸鸭蛋我送你了！NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rwnpc0603a={id="rwnpc0603a",baseId="rwnpc0603",combatid={1,1001},name="路大江",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="redoc",